     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.db.MessageRepository;
     4	import com.pousadamarealta.db.ReservationRepository;
     5	import com.pousadamarealta.db.RoomRepository;
     6	import com.pousadamarealta.model.Reservation;
     7	import com.pousadamarealta.model.RatePlan;
     8	import com.pousadamarealta.model.ReservationStatus;
     9	import com.pousadamarealta.model.Room;
    10	import com.pousadamarealta.notification.ReservationEventDispatcher;
    11	import com.pousadamarealta.util.DateFormatter;
    12	import com.pousadamarealta.util.Money;
    13	import com.pousadamarealta.util.SeasonHelper;
    14	import java.math.BigDecimal;
    15	import java.sql.SQLException;
    16	import java.time.LocalDate;
    17	import java.util.Optional;
    18	
    19	public class ReservationService {
    20	    public static Reservation createReservation(
    21	            int roomNumber,
    22	            String guestName,
    23	            String guestEmail,
    24	            String guestCpf,
    25	            LocalDate checkIn,
    26	            LocalDate checkOut,
    27	            int guests,
    28	            RatePlan ratePlan) throws SQLException {
    29	
    30	        Room room = RoomRepository.findByNumber(roomNumber)
    31	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
    32	
    33	        if (guests < 1 || guests > room.capacity()) {
    34	            if (guests < 1) {
    35	                throw new IllegalArgumentException("INVALID_REQUEST");
    36	            }
    37	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    41	            throw new IllegalArgumentException("INVALID_REQUEST");
    42	        }
    43	
    44	        var conflicts = ReservationRepository.findConflicting(roomNumber, checkIn, checkOut);
    45	        if (!conflicts.isEmpty()) {
    46	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    47	        }
    48	
    49	        int nights = SeasonHelper.countNights(checkIn, checkOut);
    50	        BigDecimal nightlyRate = room.nightlyRate();
    51	
    52	        BigDecimal subtotal = BigDecimal.ZERO;
    53	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    54	            BigDecimal dailyRate = nightlyRate;
    55	            if (SeasonHelper.isHighSeason(date)) {
    56	                dailyRate = Money.multiply(nightlyRate, new BigDecimal("1.20"));
    57	            }
    58	            subtotal = Money.add(subtotal, dailyRate);
    59	        }
    60	
    61	        BigDecimal discount = ratePlan == RatePlan.NON_REFUNDABLE
    62	            ? Money.percent(subtotal, 15)
    63	            : BigDecimal.ZERO;
    64	
    65	        BigDecimal total = Money.subtract(subtotal, discount);
    66	
    67	        Reservation reservation = new Reservation(
    68	            0,
    69	            roomNumber,
    70	            guestName,
    71	            guestEmail,
    72	            guestCpf,
    73	            checkIn,
    74	            checkOut,
    75	            guests,
    76	            ratePlan,
    77	            nights,
    78	            subtotal,
    79	            discount,
    80	            total,
    81	            ReservationStatus.PENDING,
    82	            BigDecimal.ZERO,
    83	            null
    84	        );
    85	
    86	        long id = ReservationRepository.insert(reservation);
    87	        reservation.id = id;
    88	        return reservation;
    89	    }
    90	
    91	    public static Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws SQLException {
    92	        Reservation reservation = ReservationRepository.findById(reservationId)
    93	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
    94	
    95	        if (reservation.status != ReservationStatus.PENDING) {
    96	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    97	        }
    98	
    99	        reservation.status = ReservationStatus.CONFIRMED;
   100	        reservation.amountPaid = amountPaid;
   101	        ReservationRepository.update(reservation);
   102	
   103	        sendConfirmationEmail(reservation);
   104	        ReservationEventDispatcher.fireOnConfirmed(reservation);
   105	
   106	        return reservation;
   107	    }
   108	
   109	    public static Reservation checkIn(long reservationId) throws SQLException {
   110	        Reservation reservation = ReservationRepository.findById(reservationId)
   111	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   112	
   113	        if (reservation.status != ReservationStatus.CONFIRMED) {
   114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   115	        }
   116	
   117	        reservation.status = ReservationStatus.CHECKED_IN;
   118	        ReservationRepository.update(reservation);
   119	        return reservation;
   120	    }
   121	
   122	    public static Reservation checkOut(long reservationId) throws SQLException {
   123	        Reservation reservation = ReservationRepository.findById(reservationId)
   124	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   125	
   126	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   127	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   128	        }
   129	
   130	        reservation.status = ReservationStatus.CHECKED_OUT;
   131	        ReservationRepository.update(reservation);
   132	        return reservation;
   133	    }
   134	
   135	    public static Reservation cancelReservation(long reservationId) throws SQLException {
   136	        Reservation reservation = ReservationRepository.findById(reservationId)
   137	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   138	
   139	        if (reservation.status == ReservationStatus.CHECKED_OUT ||
   140	            reservation.status == ReservationStatus.CANCELLED ||
   141	            reservation.status == ReservationStatus.CHECKED_IN) {
   142	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   143	        }
   144	
   145	        if (reservation.status == ReservationStatus.CONFIRMED) {
   146	            if (reservation.ratePlan == RatePlan.STANDARD) {
   147	                reservation.refund = reservation.amountPaid;
   148	            } else {
   149	                reservation.refund = BigDecimal.ZERO;
   150	            }
   151	        } else {
   152	            reservation.refund = BigDecimal.ZERO;
   153	        }
   154	
   155	        reservation.status = ReservationStatus.CANCELLED;
   156	        ReservationRepository.update(reservation);
   157	
   158	        ReservationEventDispatcher.fireOnCancelled(reservation);
   159	
   160	        return reservation;
   161	    }
   162	
   163	    public static Optional<Reservation> getReservation(long reservationId) throws SQLException {
   164	        return ReservationRepository.findById(reservationId);
   165	    }
   166	
   167	    private static void sendConfirmationEmail(Reservation reservation) throws SQLException {
   168	        String document = generateDocument(reservation);
   169	        String body = String.format(
   170	            "Olá, %s!\n\n" +
   171	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   172	            "%s\n\n" +
   173	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   174	            "Até breve!",
   175	            reservation.guestName,
   176	            document
   177	        );
   178	
   179	        MessageRepository.insert("EMAIL", reservation.guestEmail,
   180	            "Reserva confirmada - Pousada Maré Alta", body);
   181	    }
   182	
   183	    public static String generateDocument(Reservation reservation) throws SQLException {
   184	        StringBuilder sb = new StringBuilder();
   185	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.id));
   186	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.guestName, reservation.guestCpf));
   187	        sb.append(String.format("Quarto: %d (%s)\n",
   188	            reservation.roomNumber,
   189	            getRoomType(reservation.roomNumber)));
   190	
   191	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
   192	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
   193	            DateFormatter.format(reservation.checkIn),
   194	            DateFormatter.format(reservation.checkOut),
   195	            nightsLabel));
   196	
   197	        sb.append(String.format("Diárias: %s\n", DateFormatter.formatCurrency(reservation.subtotal)));
   198	
   199	        if (reservation.discount.signum() > 0) {
   200	            sb.append(String.format("Desconto: %s\n", DateFormatter.formatCurrency(reservation.discount)));
   201	        }
   202	
   203	        sb.append(String.format("Total: %s", DateFormatter.formatCurrency(reservation.total)));
   204	
   205	        return sb.toString();
   206	    }
   207	
   208	    private static String getRoomType(int roomNumber) throws SQLException {
   209	        return RoomRepository.findByNumber(roomNumber)
   210	            .map(r -> r.type().toString())
   211	            .orElse("UNKNOWN");
   212	    }
   213	}
