     8	public class FinanceNotifier implements ReservationEventListener {
     9	    private static final String EMAIL = "financeiro@pousadamarealta.com.br";
    10	
    11	    @Override
    12	    public void onConfirmed(Reservation reservation) {
    13	        String subject = String.format("Pagamento recebido - reserva %d", reservation.id);
    14	        String body = String.format("Valor: %s", DateFormatter.formatCurrency(reservation.amountPaid));
    15	        sendMessage(subject, body);
    16	    }
    17	
    18	    @Override
    19	    public void onCancelled(Reservation reservation) {
    20	        if (reservation.refund != null && reservation.refund.signum() > 0) {
    21	            String subject = String.format("Reembolso - reserva %d", reservation.id);
    22	            String body = String.format("Valor: %s", DateFormatter.formatCurrency(reservation.refund));
    23	            sendMessage(subject, body);
    24	        }
    25	    }
    26	
    27	    private void sendMessage(String subject, String body) {
    28	        try {
    29	            MessageRepository.insert("EMAIL", EMAIL, subject, body);
    30	        } catch (SQLException e) {
    31	            throw new RuntimeException("Failed to send message", e);
    32	        }
    33	    }
    34	}
