     1	package com.pousadamarealta.notification;
     2	
     3	import com.pousadamarealta.model.Reservation;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	
     7	public class ReservationEventDispatcher {
     8	    private static final List<ReservationEventListener> listeners = new ArrayList<>();
     9	
    10	    public static void addListener(ReservationEventListener listener) {
    11	        listeners.add(listener);
    12	    }
    13	
    14	    public static void removeListener(ReservationEventListener listener) {
    15	        listeners.remove(listener);
    16	    }
    17	
    18	    public static void fireOnConfirmed(Reservation reservation) {
    19	        listeners.forEach(l -> l.onConfirmed(reservation));
    20	    }
    21	
    22	    public static void fireOnCancelled(Reservation reservation) {
    23	        listeners.forEach(l -> l.onCancelled(reservation));
    24	    }
    25	}
