   111	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   112	
   113	        if (reservation.status != ReservationStatus.CONFIRMED) {
   114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   115	        }
   116	
   117	        reservation.status = ReservationStatus.CHECKED_IN;
   118	        ReservationRepository.update(reservation);
   119	        return reservation;
   120	    }
   121	
   122	    public static Reservation checkOut(long reservationId) throws SQLException {
   123	        Reservation reservation = ReservationRepository.findById(reservationId)
   124	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   125	
   126	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   127	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   128	        }
   129	
   130	        reservation.status = ReservationStatus.CHECKED_OUT;
   131	        ReservationRepository.update(reservation);
   132	        return reservation;
   133	    }
   134	
   135	    public static Reservation cancelReservation(long reservationId) throws SQLException {
   136	        Reservation reservation = ReservationRepository.findById(reservationId)
   137	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   138	
   139	        if (reservation.status == ReservationStatus.CHECKED_OUT ||
   140	            reservation.status == ReservationStatus.CANCELLED ||
   141	            reservation.status == ReservationStatus.CHECKED_IN) {
   142	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   143	        }
   144	
   145	        if (reservation.status == ReservationStatus.CONFIRMED) {
   146	            if (reservation.ratePlan == RatePlan.STANDARD) {
   147	                reservation.refund = reservation.amountPaid;
   148	            } else {
   149	                reservation.refund = BigDecimal.ZERO;
   150	            }
   151	        } else {
   152	            reservation.refund = BigDecimal.ZERO;
   153	        }
   154	
   155	        reservation.status = ReservationStatus.CANCELLED;
   156	        ReservationRepository.update(reservation);
   157	
   158	        ReservationEventDispatcher.fireOnCancelled(reservation);
   159	
   160	        return reservation;
   161	    }
