   172	            "%s\n\n" +
   173	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   174	            "Até breve!",
   175	            reservation.guestName,
   176	            document
   177	        );
   178	
   179	        MessageRepository.insert("EMAIL", reservation.guestEmail,
   180	            "Reserva confirmada - Pousada Maré Alta", body);
