   183	    public static String generateDocument(Reservation reservation) throws SQLException {
   184	        StringBuilder sb = new StringBuilder();
   185	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.id));
   186	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.guestName, reservation.guestCpf));
   187	        sb.append(String.format("Quarto: %d (%s)\n",
   188	            reservation.roomNumber,
   189	            getRoomType(reservation.roomNumber)));
   190	
   191	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
   192	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
   193	            DateFormatter.format(reservation.checkIn),
   194	            DateFormatter.format(reservation.checkOut),
   195	            nightsLabel));
   196	
   197	        sb.append(String.format("Diárias: %s\n", DateFormatter.formatCurrency(reservation.subtotal)));
   198	
   199	        if (reservation.discount.signum() > 0) {
   200	            sb.append(String.format("Desconto: %s\n", DateFormatter.formatCurrency(reservation.discount)));
   201	        }
   202	
   203	        sb.append(String.format("Total: %s", DateFormatter.formatCurrency(reservation.total)));
   204	
   205	        return sb.toString();
   206	    }
