     7	    public static boolean isHighSeason(LocalDate date) {
     8	        int month = date.getMonthValue();
     9	        int day = date.getDayOfMonth();
    10	
    11	        if (month == Month.JULY.getValue()) return true;
    12	
    13	        if (month == Month.DECEMBER.getValue() && day >= 15) return true;
    14	
    15	        if (month == Month.JANUARY.getValue()) return true;
    16	        if (month == Month.FEBRUARY.getValue()) return true;
    17	
    18	        return false;
    19	    }
